	if padding > bytes-used {
		return TableRefuseTruncated
	}
	used += padding
	if uintptr(base)%64 != 0 {
		return TableRefuseUnalignedBase
	}
	block.Base = base
	block.Projection = (*StrangerEntryBlockProjection)(base)
	block.Bytes = used
	return nil
